// Shape of src/data/site-data.json (generated by scripts/build-data.mjs).

export type Point = { t: string; actual: number; expected: number; flagged: boolean };

export type Anomaly = {
  t: string;
  actual: number;
  expected: number;
  residual: number;
  pctAbove: number;
  percentile: number;
  periodId: number;
  context: Point[];
};

export type ScorePair = { mae: number; rmse: number };

export type ModelData = {
  dataset: {
    name: string;
    what_is_measured: string;
    rows: number;
    interval: string;
    units: string;
    license: string;
  };
  split: string;
  periods: { train: [string, string]; validation: [string, string]; test: [string, string] };
  validation: { name: string; mae: number; rmse: number; features: string[] | null; selected: boolean }[];
  selected: { name: string; features: string[]; params: Record<string, unknown>; rule: string };
  finalTest: { baseline: ScorePair; model: ScorePair; improvement: ScorePair };
  persistence: { validation: ScorePair; test: ScorePair } | null;
  anomalyMethod: {
    thresholdWh: number;
    rule: string;
    validationPositive: number;
    flagged: number;
    periods: number;
    injection: {
      events: number;
      event_length_minutes: number;
      added_wh_per_interval: number;
      injected_intervals_flagged_pct: number;
      events_with_at_least_one_flag: number;
    } | null;
  };
  featureImportance: { feature: string; importance: number }[] | null;
  candidateFeatures: { all: string[]; kept: string[] } | null;
  leakageCheckPassed: boolean | null;
};

export type ContextPoint = Point & {
  residual: number;
  pctAbove: number;
  percentile: number;
  rule: string;
  context: Point[];
};

export type Failure = {
  t: string;
  day: string;
  expected: number;
  actual: number;
  error: number;
  absError: number;
  direction: string;
  flagged: boolean;
  previousInterval: number | null;
  context: Point[];
};

export type SiteData = {
  generatedAt: string;
  sources: Record<string, "ok" | "missing">;
  warnings: string[];
  model: ModelData | null;
  hero: Anomaly | null;
  heroLine: { values: number[]; focusIndex: number; start: string; end: string } | null;
  chart: { rule: string; start: string; end: string; flaggedInWindow: number; points: Point[] } | null;
  anomalies: Anomaly[] | null;
  context: {
    highButNormal: ContextPoint | null;
    lowButUnusual: ContextPoint | null;
    usageRule: { n: number; overlap: number; minUsageInRule: number | null; explanation: string };
  } | null;
  failures: Failure[] | null;
};
